import{_ as o}from"./chunks/home.pc.en.BIVUBvtu.js";import{_ as t,o as a,c as r,a5 as d}from"./chunks/framework.D47SInms.js";const n="/RBQ/nightly/images/app/home-dock-scan.pc.en.png",i="/RBQ/nightly/images/app/home-dock-view.pc.en.png",s="/RBQ/nightly/images/app/home-dock-view-off.pc.en.png",b=JSON.parse('{"title":"Camera & Vision","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/camera-vision.md","filePath":"manual/gui/camera-vision.md","lastUpdated":1791600043000}'),c={name:"manual/gui/camera-vision.md"};function h(l,e,p,g,m,u){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="camera-vision" tabindex="-1">Camera &amp; Vision <a class="header-anchor" href="#camera-vision" aria-label="Permalink to &quot;Camera &amp; Vision&quot;">​</a></h1><p>The center of the control home is the viewport. It shows either the live 3D pose of the robot or one of its camera streams, and it is where tap-to-go and the vision overlays live.</p><p><img src="'+o+'" alt="Control home with the viewport"></p><h2 id="switching-the-viewport-source" tabindex="-1">Switching the viewport source <a class="header-anchor" href="#switching-the-viewport-source" aria-label="Permalink to &quot;Switching the viewport source&quot;">​</a></h2><p>Tap the source name at the top center of the viewport to open the source list. The list shows only the sources whose cameras the robot actually reports, so it is shorter on robots with fewer cameras.</p><table tabindex="0"><thead><tr><th>Source</th><th>Shows</th><th>Needs</th></tr></thead><tbody><tr><td><code>3D</code></td><td>Live 3D pose of the robot (always available)</td><td>—</td></tr><tr><td><code>Front</code> / <code>Rear</code> / <code>Left</code> / <code>Right</code></td><td>A single body camera</td><td>That camera</td></tr><tr><td><code>Stairs</code></td><td>Stair-climbing view composed from the front, rear, and belly cameras</td><td>Front, rear, and all four belly cameras</td></tr><tr><td><code>Quad</code></td><td>Four body cameras in one 2×2 frame</td><td>Front, rear, left, and right cameras</td></tr><tr><td><code>Panorama</code></td><td>Four body cameras stitched horizontally</td><td>Front, rear, left, and right cameras</td></tr><tr><td><code>CCTV</code></td><td>The optional PTZ unit&#39;s color camera</td><td>PTZ color camera (see <a href="/RBQ/nightly/manual/gui/ptz.html">PTZ camera</a>)</td></tr><tr><td><code>Thermal</code></td><td>The PTZ unit&#39;s thermal camera</td><td>PTZ thermal sensor</td></tr><tr><td><code>PTZ Mix</code></td><td>Color and thermal combined</td><td>PTZ color camera and thermal sensor</td></tr><tr><td><code>SLAM</code></td><td>Live SLAM map</td><td>LiDAR</td></tr></tbody></table><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#control-home">Developer mode</a>.</p></blockquote><p>The video keeps its 16:9 shape and fits into the space below the top bar. On wide screens, the leftover side gutters hold the cards and virtual joysticks. The source list never covers the top bar, so the E-STOP stays reachable while the menu is open.</p><p>While another device is driving and this one is spectating, the list holds only <code>3D</code> and <code>Driver&#39;s view</code> — the driving device picks the camera. See <a href="/RBQ/nightly/manual/gui/emergency.html#spectating">Spectating</a>.</p><h2 id="view-options-right-card" tabindex="-1">View options (right card) <a class="header-anchor" href="#view-options-right-card" aria-label="Permalink to &quot;View options (right card)&quot;">​</a></h2><p>The right card, titled <code>OBSERVE</code>, holds what you look at and listen to. Tap its round button to fold the card into a circle or open it again. The card starts open, and the app remembers your choice.</p><ul><li><code>Vision</code> — opens the <code>Vision</code> popover: the <code>Point to Go</code> switch (see below) and vision toggles such as <code>Night mode</code> and <code>Dock scan</code>.</li></ul><table tabindex="0"><thead><tr><th>Row</th><th>Effect</th></tr></thead><tbody><tr><td><code>Night mode</code></td><td>Low-light capture</td></tr><tr><td><code>Stealth</code></td><td>LEDs and indicators off</td></tr><tr><td><code>GUIDE</code></td><td>Drive guide lines drawn into the video</td></tr><tr><td><code>FACE</code></td><td>Face detection boxes</td></tr><tr><td><code>Dock scan</code></td><td>Look for docking markers</td></tr><tr><td><code>Heightmap</code></td><td>Terrain elevation overlay. <code>└ Edge emphasis</code> below it is enabled only while <code>Heightmap</code> is on</td></tr><tr><td><code>IR projector</code></td><td>Projects an infrared dot pattern for the depth camera, so it can measure depth on plain walls and floors. Shown only on robots whose depth camera has a projector</td></tr><tr><td><code>Video resolution</code></td><td>The robot&#39;s video output: <code>720p</code> / <code>540p</code> / <code>360p</code> — lower it on a weak link</td></tr></tbody></table><p><code>IR projector</code> and <code>Video resolution</code> show the state the robot reports.</p><ul><li><code>Scene</code> — opens <code>3D scene settings</code>. Shown only while the <code>3D</code> source is selected.</li><li><code>Audio</code> — opens the walkie-talkie (see <a href="/RBQ/nightly/manual/gui/audio.html">Audio</a>).</li></ul><p><code>Speed HUD</code> and <code>Gyro widget</code> are in <strong>Settings › App settings</strong>.</p><p><code>3D scene settings</code> holds:</p><ul><li><code>Grid</code> — Grid ON / Grid OFF plus a grid size in meters (<code>−</code> / <code>+</code> or type a value).</li><li><code>Scene theme</code> — background color presets.</li><li><code>Camera behavior</code> — <code>Top</code>, <code>Robot</code>, or <code>3D</code> camera follow mode.</li><li><code>LiDAR (display)</code> — <code>Off</code> / <code>On</code> for the point cloud.</li></ul><h2 id="tap-to-go-p2g" tabindex="-1">Tap-to-go (P2G) <a class="header-anchor" href="#tap-to-go-p2g" aria-label="Permalink to &quot;Tap-to-go (P2G)&quot;">​</a></h2><p>With <code>Point to Go</code> on, tapping a point on the ground in the front camera makes the robot walk to it. An aim marker appears where you press and <strong>follows your finger as you drag</strong>, and the command goes to wherever you lift your finger, so you can line the point up before you let go. <strong>Drag off the video before you release and nothing is sent</strong> — that is how you cancel a press you did not mean. The robot itself draws the path and target on the video it streams, so the marker is only momentary feedback.</p><p>A tap moves the robot only when <strong>all four</strong> of these are true:</p><ol><li><code>Point to Go</code> is switched on in the <code>Vision</code> popover (the viewport shows a blue border while it is on).</li><li>The viewport source is <code>Front</code>. On every other source the switch is grayed out and reads <code>Front camera source only</code>, because the app reads the tap in front-camera coordinates.</li><li>The robot is standing and ready to walk. The app does not check this — the robot decides whether to act on the command.</li><li>You tapped <strong>ground that is visible in the image</strong>. The app sends every tap, but the robot walks only when the point lands on ground it can see. A tap on the horizon, a wall, or the sky shows the marker and does nothing else.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>While <code>Point to Go</code> is on, the whole video area is a tap target — an accidental touch sends a walk command. Turn it off as soon as you are done.</p></div><h2 id="docking-marker-overlay" tabindex="-1">Docking-marker overlay <a class="header-anchor" href="#docking-marker-overlay" aria-label="Permalink to &quot;Docking-marker overlay&quot;">​</a></h2><p><img src="'+n+'" alt="Docking-marker overlay on the front camera"></p><p>When the robot sees a docking marker (ArUco), a <code>Start docking</code> button appears over the video — on <code>3D</code> and on every camera source, including <strong>Front</strong>, <strong>Rear</strong> and <strong>Stairs</strong>. On the sources that show the camera which found it, the app draws a box around the marker itself. The other sources show a picture of the docking marker at the bottom of the screen instead — tapping it also starts docking.</p><p><code>Dock scan</code> in the <code>Vision</code> popover switches the robot&#39;s marker detection on and off; the detection itself runs on the camera images. It is on by default. While docking runs, the marker is drawn no matter what this toggle says — watching it is the whole point.</p><h2 id="dock-view" tabindex="-1">Dock View <a class="header-anchor" href="#dock-view" aria-label="Permalink to &quot;Dock View&quot;">​</a></h2><p><img src="'+i+'" alt="Dock View during a docking run"></p><p>Starting docking opens <strong>Dock View</strong>. It replaces the viewport with the three cameras the robot uses for docking and shows what the robot detects, so you can tell why a docking run succeeds or fails.</p><p>Closing it does not stop docking. While the run is under way, the docking banner stays at the top of the screen, and <code>Tap to view</code> on the banner opens Dock View again.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Dock View exists only during a docking run.</strong> The banner disappears four seconds after docking completes, and it is not shown at all once a run has failed — from then on there is no way back into the screen. Watch a run while it is happening — to see the cameras again, you have to start another docking run.</p></div><p>The video band holds three panes: <strong>FRONT</strong>, <strong>REAR</strong>, and <strong>BOTTOM2</strong> (the downward infrared camera). The pane whose camera found the marker is outlined in orange, and a box and the marker axes are drawn on the marker. The pane label also shows the marker IDs used and, for <strong>BOTTOM2</strong>, whether the IR projector is on.</p><p>Below the band:</p><ul><li><strong>Progress</strong> — <code>Approach 1</code>, <code>Approach 2</code>, <code>Approach 3</code>, <code>Sit</code>, <code>Charge</code>. <code>Charge</code> lights up only once the robot measures charging current.</li><li><strong>Status</strong> — the current step in words, and the reason when a run fails.</li><li><strong>Detection hints</strong> — shown when the robot keeps discarding the marker, for example <code>Marker detection quality is low</code>. When a run has ended because no marker was found, the hint also says what to do.</li><li><strong>Buttons</strong> — <code>Stop docking</code> while docking runs; <code>Undock</code> once the robot is charging; <code>Resume docking</code> after a failed run; <code>Stand up</code> when all retries are used; <code>Close</code> at any time.</li></ul><p><code>Undock</code> and <code>Stand up</code> lift a seated robot, so they are press-and-hold buttons. Hold one and it fills from the left. The command goes out the moment the fill reaches the far edge, about a second later. Let go before it is full and nothing is sent.</p><p>While the robot retries on its own, the buttons read <code>Retrying automatically</code> and there is nothing for you to do.</p><p>Once docking finishes, the charge level appears after three seconds. Five seconds later the cameras turn themselves off and the band reads <code>Docking finished — the camera view is turned off</code>. A docked robot sits on the charger for hours, so there is nothing left to watch.</p><p><img src="'+s+'" alt="Dock View after the cameras are turned off"></p>',39)])])}const k=t(c,[["render",h]]);export{b as __pageData,k as default};
